'use strict';
/* public/js/40-fx.js -- dirt particles, item pops, rain, WebAudio sound effects. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- dirt particles ---------- */
const PMAX=260;
const pMesh=new T.InstancedMesh(new T.BoxGeometry(0.13,0.13,0.13),M(0xc98f55),PMAX);pMesh.instanceMatrix.setUsage(T.DynamicDrawUsage);pMesh.castShadow=false;pMesh.frustumCulled=false;scene.add(pMesh);
const parts=[];for(let i=0;i<PMAX;i++)parts.push({life:0,x:0,y:0,z:0,vx:0,vy:0,vz:0});let pNext=0;
const dummy=new T.Object3D();
function puff(x,y,z,tx,tz,n){for(let k=0;k<n;k++){const p=parts[pNext];pNext=(pNext+1)%PMAX;const dx=tx-x,dz=tz-z;p.x=x;p.y=y;p.z=z;p.vx=dx*1.1+(Math.random()-0.5)*1.4;p.vz=dz*1.1+(Math.random()-0.5)*1.4;p.vy=3+Math.random()*2.5;p.life=0.9+Math.random()*0.4}}
function updateParts(dt){for(let i=0;i<PMAX;i++){const p=parts[i];if(p.life>0){p.life-=dt;p.vy-=14*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;const g=groundAt(p.x,p.z);if(p.y<g){p.y=g;p.vx*=0.4;p.vz*=0.4;p.vy=0}dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.x*3,p.z*3,0);dummy.scale.setScalar(Math.min(1,p.life*2.5))}else dummy.scale.setScalar(0);dummy.updateMatrix();pMesh.setMatrixAt(i,dummy.matrix)}pMesh.instanceMatrix.needsUpdate=true}

/* found-item pop */
const pops=[];
function itemMesh(type){
  if(ITEM_MODELS[type]){const g=ITEM_MODELS[type].clone();g.scale.copy(ITEM_MODELS[type].scale);return g}   // Blender model (23-models.js), once loaded
  const c=LOOT[type].color;
  if(type==='suitcase'){const g=new T.Group();const b=box(0.8,0.55,0.25,c);const h=box(0.3,0.08,0.06,0x2a1a0e);h.position.y=0.32;g.add(b,h);return g}
  if(type==='kb')return cyl(0.06,0.06,0.3,8,c);
  if(type==='shoe'){return new T.Mesh(new T.TorusGeometry(0.16,0.045,5,10,Math.PI*1.5),M(c))}
  if(type==='fossil')return box(0.4,0.08,0.25,c);
  if(type==='jar')return cyl(0.12,0.12,0.24,8,c);
  if(type==='arrow')return new T.Mesh(new T.ConeGeometry(0.1,0.28,3),M(c));
  if(type==='can')return cyl(0.09,0.09,0.2,8,c);
  if(type==='spoon')return box(0.05,0.03,0.3,c);
  if(type==='lipstick')return cyl(0.04,0.04,0.2,8,c);
  if(type==='sploosh')return cyl(0.13,0.11,0.26,8,c);
  if(type==='locket')return new T.Mesh(new T.TorusGeometry(0.1,0.035,6,12),M(c));
  if(type==='pistol'){const g=new T.Group();const b=box(0.32,0.07,0.06,c),h=box(0.07,0.16,0.06,0x5a3a1e);h.position.set(-0.12,-0.08,0);g.add(b,h);return g}
  return cyl(0.07,0.07,0.03,8,c);
}
/* size, float height, timing and spin come from the tester's control center (11-tune.js, Finds tab) */
const bigFind=type=>!!(LOOT[type].heavy||LOOT[type].key);
function popItem(it,hx,hz){const m=itemMesh(it.type);const y=groundAt(hx,hz);m.scale.multiplyScalar(tune(bigFind(it.type)?'finds.bigScale':'finds.smallScale'));
  m.position.set(hx,y+tune('finds.start'),hz);scene.add(m);pops.push({m,t:0,y0:y,s0:m.scale.x})}
function updatePops(dt){for(let i=pops.length-1;i>=0;i--){const p=pops[i];p.t+=dt;
  const up=Math.sin(Math.min(p.t/tune('finds.riseTime'),1)*Math.PI*0.5);p.m.position.y=p.y0+tune('finds.start')+up*tune('finds.rise');p.m.rotation.y+=dt*tune('finds.spin');
  if(p.t>tune('finds.hold')){p.m.scale.multiplyScalar(0.85);if(p.m.scale.x<0.05*p.s0){scene.remove(p.m);pops.splice(i,1)}}}}

/* Warden's flags around the search area */
const flags=new T.Group();flags.visible=false;scene.add(flags);
for(let i=0;i<14;i++){const a=i/14*Math.PI*2;const x=SEARCH.x+Math.cos(a)*SEARCH.r,z=SEARCH.z+Math.sin(a)*SEARCH.r;const g=new T.Group();const p=cyl(0.04,0.04,1.8,5,0xdcdcdc);p.position.y=0.9;const f=box(0.5,0.3,0.02,0xd12a2a);f.position.set(0.25,1.6,0);g.add(p,f);g.position.set(x,baseH(x,z),z);flags.add(g)}

/* rain */
const RAIN=2200;const rainGeo=new T.BufferGeometry();const rainPos=new Float32Array(RAIN*6);rainGeo.setAttribute('position',new T.BufferAttribute(rainPos,3));
const rain=new T.LineSegments(rainGeo,new T.LineBasicMaterial({color:0xcfe0ee,transparent:true,opacity:0.55}));rain.visible=false;rain.frustumCulled=false;scene.add(rain);
const rainSeed=[];for(let i=0;i<RAIN;i++)rainSeed.push({x:(Math.random()-0.5)*60,y:Math.random()*30,z:(Math.random()-0.5)*60,v:18+Math.random()*8});
function updateRain(dt){if(!rain.visible)return;const cx=camera.position.x,cz=camera.position.z;for(let i=0;i<RAIN;i++){const d=rainSeed[i];d.y-=d.v*dt;if(d.y<-2){d.y=28;d.x=(Math.random()-0.5)*60;d.z=(Math.random()-0.5)*60}const x=cx+d.x,z=cz+d.z,y=d.y+P.y;rainPos.set([x,y,z,x-0.05,y+0.7,z],i*6)}rainGeo.attributes.position.needsUpdate=true}

/* ---------- audio: CC0 foley and ambience, with synthesized fallbacks ---------- */
let AC=null,master=null,noiseBuf=null,muted=false,rainGain=null,windNoiseGain=null,windLfoGain=null;
// A/B modes are local to this browser. Preserve the original wind by default; every changed sound is selectable by category.
const AUDIO_MODE={wind:'original',ambience:'recorded',rain:'recorded',steps:'recorded',dig:'recorded',metal:'recorded',props:'recorded'};
function audioModeStatus(){return Object.entries(AUDIO_MODE).map(([k,v])=>`${k}: ${v}`).join(', ')}
function setAudioMode(category,mode){
  if(category==='all'){for(const k of Object.keys(AUDIO_MODE))AUDIO_MODE[k]=mode}
  else AUDIO_MODE[category]=mode;
  return audioModeStatus();
}
const AUDIO_FILES={
  shovel:'shovel.mp3',wind:'wind.mp3',birds:'birds.mp3',crickets:'crickets.mp3',rain:'rain.mp3',
  'step-sand-1':'step-sand-1.mp3','step-sand-2':'step-sand-2.mp3','step-sand-3':'step-sand-3.mp3',
  'step-stone-1':'step-stone-1.mp3','step-stone-2':'step-stone-2.mp3','step-stone-3':'step-stone-3.mp3',
  cloth1:'cloth1.mp3',cloth2:'cloth2.mp3',doorOpen:'doorOpen_1.mp3',metalClick:'metalClick.mp3',
  'call-hawk':'call-hawk.mp3','call-dove':'call-dove.mp3','call-owl':'call-owl.mp3',
  'call-coyotes-distant':'call-coyotes-distant.mp3','call-coyotes-near':'call-coyotes-near.mp3',
  'dig-1':'dig-shovel-sand-l1.mp3','dig-2':'dig-shovel-sand-r1.mp3','dig-3':'dig-shovel-sand-l3.mp3','dig-4':'dig-shovel-sand-r3.mp3'
};
const audioBuffers=new Map(),audioLoads=new Map(),ambientLoops=new Map();
function loadAudioClip(name){
  if(!AC||!AUDIO_FILES[name])return Promise.resolve(null);
  if(audioBuffers.has(name))return Promise.resolve(audioBuffers.get(name));
  if(audioLoads.has(name))return audioLoads.get(name);
  const p=fetch('/audio/'+AUDIO_FILES[name]).then(r=>{if(!r.ok)throw Error('audio unavailable');return r.arrayBuffer()})
    .then(bytes=>AC.decodeAudioData(bytes)).then(buffer=>{audioBuffers.set(name,buffer);return buffer}).catch(()=>null);
  audioLoads.set(name,p);return p;
}
const CLIP_VOL=n=>/^step-/.test(n)?'vol.steps':/^dig-|^shovel$/.test(n)?'vol.dig':n==='metalClick'?'vol.metal':/^cloth|^door/.test(n)?'vol.props':null;
function playAudioClip(name,volume=1,rate=1){
  if(!AC)return false;
  const vk=CLIP_VOL(name);if(vk)volume*=tune(vk);
  const buffer=audioBuffers.get(name);if(!buffer){loadAudioClip(name);return false}
  const src=AC.createBufferSource(),gain=AC.createGain();src.buffer=buffer;src.playbackRate.value=rate;
  gain.gain.value=volume;src.connect(gain).connect(fxBus);src.onended=()=>{src.disconnect();gain.disconnect()};src.start();return true;
}
function setAmbientClip(name,volume){
  if(!AC)return;
  let loop=ambientLoops.get(name);
  if(!loop){const buffer=audioBuffers.get(name);if(!buffer){loadAudioClip(name);return}
    const src=AC.createBufferSource(),gain=AC.createGain();src.buffer=buffer;src.loop=true;gain.gain.value=0;
    src.connect(gain).connect(fxBus);src.start();loop={src,gain};ambientLoops.set(name,loop);
  }
  loop.gain.gain.setTargetAtTime(volume*tuneOr('vol.'+name,1),AC.currentTime,0.9);
}
let footstepT=0,footstepN=0;
function updateFootsteps(dt){
  if(!AC||!S.started)return;
  if(AUDIO_MODE.steps==='original'){footstepT=0;return}
  if(!P.moving||!P.grounded||S.ko||S.inBed!=null||digHeld){footstepT=0;return}
  footstepT-=dt;if(footstepT>0)return;
  const running=P.anim===4,kind=inTent()?'stone':'sand';
  footstepT=running?0.29:P.crouch?0.58:0.43;
  footstepN=(footstepN+1)%3;
  // 10% of the original levels (JT: footsteps too loud); were 0.4 running / 0.32 walking, 0.05 for the loading fallback
  if(!playAudioClip(`step-${kind}-${footstepN+1}`,running?0.04:0.032,0.92+Math.random()*0.16))noise(0.07,280,0.6,0.005,'lowpass');
}
const BIRDS_LEVEL=0;   // the always-on day bird loop is off (JT: too much); it was 0.24. birds.mp3 stays for an occasional-call idea
/* Desert calls: now and then (every 3-5 minutes, randomised) one far-off animal calls from a random side, picked
   for the time of day. Out on the lake only; in a tent or a dust storm the call waits and tries again shortly. */
const DESERT_CALLS=[
  {name:'call-hawk',when:'day',vol:0.55},
  {name:'call-dove',when:'morning',vol:0.4},
  {name:'call-coyotes-distant',when:'night',vol:0.55},
  {name:'call-coyotes-near',when:'night',vol:0.45},
  {name:'call-owl',when:'night',vol:0.4},
];
const CALL_GAP=[180,300];   // seconds between calls
let callAt=0,lastCall='';
function callFits(c){const night=nightF()>0.5,h=hourOf(clockT());return c.when==='night'?night:c.when==='morning'?!night&&h<10:!night}
function playDesertCall(c){
  if(!AC)return false;const buffer=audioBuffers.get(c.name);if(!buffer){loadAudioClip(c.name);return false}
  const src=AC.createBufferSource(),gain=AC.createGain(),pan=AC.createStereoPanner();
  src.buffer=buffer;src.playbackRate.value=0.97+Math.random()*0.06;gain.gain.value=c.vol*tuneOr('vol.calls',1);pan.pan.value=(Math.random()*2-1)*0.8;
  src.connect(gain).connect(pan).connect(fxBus);src.onended=()=>{src.disconnect();gain.disconnect();pan.disconnect()};src.start();lastCall=c.name;return true;
}
function desertCallNow(){   // the console's "audio call": play one that fits right now
  const fit=DESERT_CALLS.filter(callFits),c=fit[(Math.random()*fit.length)|0];return c&&playDesertCall(c)?c.name:null;
}
function updateDesertCalls(outside,dust){
  const now=AC.currentTime;
  if(!callAt){callAt=now+CALL_GAP[0]+Math.random()*(CALL_GAP[1]-CALL_GAP[0]);return}
  if(now<callAt)return;
  const fit=DESERT_CALLS.filter(c=>callFits(c)&&(c.name!==lastCall||DESERT_CALLS.filter(callFits).length===1));
  if(outside<1||dust>0.3||AUDIO_MODE.ambience!=='recorded'||!fit.length||!playDesertCall(fit[(Math.random()*fit.length)|0])){callAt=now+20+Math.random()*20;return}
  callAt=now+CALL_GAP[0]+Math.random()*(CALL_GAP[1]-CALL_GAP[0]);
}
function updateAudioScene(){
  if(!AC||!S.started)return;
  const outside=inTent()?0.14:1,night=nightF(),dust=haboobF();
  const recordedWind=AUDIO_MODE.wind==='recorded',recordedRain=AUDIO_MODE.rain==='recorded';
  setAmbientClip('wind',recordedWind?outside*(0.16+dust*0.06):0);
  setAmbientClip('birds',AUDIO_MODE.ambience==='recorded'?outside*(1-night)*(1-dust)*BIRDS_LEVEL:0);
  setAmbientClip('crickets',AUDIO_MODE.ambience==='recorded'?outside*night*(1-dust)*0.43:0);
  setAmbientClip('rain',S.won&&recordedRain?0.33:0);
  updateDesertCalls(outside,dust);
  const at=AC.currentTime;
  if(windNoiseGain)windNoiseGain.gain.setTargetAtTime((recordedWind?outside*(audioBuffers.has('wind')?0.013:0.06):0.07)*tune('vol.wind'),at,0.6);
  if(windLfoGain)windLfoGain.gain.setTargetAtTime((recordedWind?0:0.04)*tune('vol.wind'),at,0.6);
  if(rainGain)rainGain.gain.setTargetAtTime((S.won?(recordedRain&&audioBuffers.has('rain')?0.02:0.18):0)*tune('vol.rain'),at,0.6);
}
function initAudio(){
  if(AC)return;try{AC=new (window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=SETTINGS.volMaster;master.connect(AC.destination);
  fxBus=AC.createGain();fxBus.gain.value=SETTINGS.volFx;fxBus.connect(master);   // pause menu: ambient + one-shot sfx share this bus, so Effects volume is independent of Music
  noiseBuf=AC.createBuffer(1,AC.sampleRate*2,AC.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  const wind=AC.createBufferSource();wind.buffer=noiseBuf;wind.loop=true;const wf=AC.createBiquadFilter();wf.type='lowpass';wf.frequency.value=320;windNoiseGain=AC.createGain();windNoiseGain.gain.value=0.07;
  const lfo=AC.createOscillator();lfo.frequency.value=0.08;windLfoGain=AC.createGain();windLfoGain.gain.value=0.04;lfo.connect(windLfoGain).connect(windNoiseGain.gain);lfo.start();
  wind.connect(wf).connect(windNoiseGain).connect(fxBus);wind.start();
  const rn=AC.createBufferSource();rn.buffer=noiseBuf;rn.loop=true;const rf=AC.createBiquadFilter();rf.type='bandpass';rf.frequency.value=2600;rf.Q.value=0.5;rainGain=AC.createGain();rainGain.gain.value=0;rn.connect(rf).connect(rainGain).connect(fxBus);rn.start();
  for(const name of Object.keys(AUDIO_FILES))loadAudioClip(name);
  }catch(e){AC=null}
}
function noise(dur,freq,q,gain,type){if(!AC)return;gain*=tune('vol.synth');if(gain<=0)return;const s=AC.createBufferSource();s.buffer=noiseBuf;const f=AC.createBiquadFilter();f.type=type||'bandpass';f.frequency.value=freq;f.Q.value=q;const g=AC.createGain();const t=AC.currentTime;g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);s.connect(f).connect(g).connect(fxBus);s.start(t,Math.random());s.stop(t+dur+0.05)}
function tone(freq,dur,type,gain,to){if(!AC)return;gain*=tune('vol.synth');if(gain<=0)return;const o=AC.createOscillator();o.type=type||'sine';const g=AC.createGain();const t=AC.currentTime;o.frequency.setValueAtTime(freq,t);if(to)o.frequency.exponentialRampToValueAtTime(to,t+dur);g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.connect(g).connect(fxBus);o.start(t);o.stop(t+dur+0.05)}
let digClip=0;
const sfx={
  // Four shovel+sand layers played in turn so back-to-back digs never repeat; the bare shovel covers loading.
  scoop(){if(AUDIO_MODE.dig==='recorded'){const r=0.94+Math.random()*0.12;digClip=digClip%4+1;if(playAudioClip('dig-'+digClip,0.56,r)||playAudioClip('shovel',0.48,r))return}noise(0.22,420+Math.random()*260,0.7,0.55,'lowpass');tone(110,0.12,'sine',0.25,55)},
  clank(){if(AUDIO_MODE.metal==='recorded'&&playAudioClip('metalClick',1.15))return;tone(1400,0.25,'triangle',0.12,900);noise(0.08,3000,3,0.15)},
  find(){[660,880,1320].forEach((f,i)=>setTimeout(()=>tone(f,0.18,'triangle',0.16),i*85))},
  gold(){[523,659,784,1047,1319].forEach((f,i)=>setTimeout(()=>tone(f,0.3,'triangle',0.16),i*110))},
  coin(){tone(988,0.08,'square',0.07);setTimeout(()=>tone(1319,0.18,'square',0.07),70)},
  beep(s){tone(600+s*900,0.06,'square',0.045)},
  hiss(){noise(0.6,4200,1.5,0.22)},
  bite(){noise(0.3,900,1,0.5);tone(200,0.4,'sawtooth',0.18,60)},
  shout(){tone(300,0.15,'sawtooth',0.06,420)},
  splash(){noise(0.4,1200,0.7,0.3)},
  thud(){tone(80,0.2,'sine',0.35,40)}
};
